bounded_host_request.command:
set -eu
p="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$p" | sed '/^$/d' | wc -l)" -eq 1 || { echo STK04_POSTGRES_NOT_UNIQUE; exit 71; }
docker exec -i "$p" sh -c 'psql -U "$POSTGRES_USER" -d gaybbs -v ON_ERROR_STOP=1 -X -qAt' <<'STK04_SQL'
BEGIN;
DO $$
DECLARE r RECORD;
BEGIN
 SELECT * INTO r FROM posting_topics WHERE topic_id=112 FOR UPDATE;
 IF NOT FOUND OR r.board_key<>'video_chat' OR r.chat_id<>-1002373696859
   OR r.message_thread_id<>4291 OR r.enabled IS NOT TRUE
   OR r.verified_at IS NULL OR r.verified_by IS NULL
   OR r.purpose NOT IN ('announcement','sticker')
   OR r.title NOT IN ('(thread:4291)','ステッカーの公開と販売') THEN
   RAISE EXCEPTION 'STK04_POSTING_TOPIC_ROW_MISMATCH';
 END IF;
 IF EXISTS(SELECT 1 FROM posting_deliveries WHERE posting_topic_id=112) THEN
   RAISE EXCEPTION 'STK04_PREEXISTING_POSTS_REQUIRE_RECONCILE';
 END IF;
 IF EXISTS(SELECT 1 FROM posting_topics WHERE board_key='video_chat'
   AND purpose='sticker' AND chat_id=-1002373696859 AND topic_id<>112) THEN
   RAISE EXCEPTION 'STK04_OTHER_STICKER_TARGET_EXISTS';
 END IF;
END $$;
ALTER TABLE posting_topics DROP CONSTRAINT IF EXISTS posting_topics_purpose_check;
ALTER TABLE posting_topics ADD CONSTRAINT posting_topics_purpose_check
 CHECK (purpose IN ('profile','room','announcement','link','sticker'));
UPDATE posting_topics SET purpose='sticker',title='ステッカーの公開と販売'
 WHERE topic_id=112 AND chat_id=-1002373696859 AND message_thread_id=4291;
CREATE TABLE IF NOT EXISTS posting_sticker_entry_pins (
 topic_id BIGINT PRIMARY KEY REFERENCES posting_topics(topic_id) ON DELETE RESTRICT,
 creator_bot_id BIGINT NULL CHECK (creator_bot_id > 0),
 creator_bot_username TEXT NOT NULL
   CHECK (creator_bot_username ~ '^[A-Za-z][A-Za-z0-9_]{4,31}$'),
 status TEXT NOT NULL CHECK (status IN ('sending','sent','pin_requested','pinned_ack','needs_reconcile')),
 telegram_message_id BIGINT CHECK (telegram_message_id > 0),
 created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
 CHECK (status='sending' OR telegram_message_id IS NOT NULL)
);
ALTER TABLE posting_sticker_entry_pins ALTER COLUMN creator_bot_id DROP NOT NULL;
INSERT INTO posting_sticker_entry_pins
 (topic_id,creator_bot_id,creator_bot_username,status,telegram_message_id)
 VALUES (112,NULL,'CreateVdobot','pinned_ack',4652)
 ON CONFLICT (topic_id) DO NOTHING;
DO $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM posting_sticker_entry_pins WHERE topic_id=112
 AND status='pinned_ack' AND telegram_message_id=4652
 AND lower(creator_bot_username)='createvdobot') THEN
  RAISE EXCEPTION 'STK04_PIN_RECEIPT_CONFLICT';
 END IF;
END $$;
COMMIT;
SELECT 'STK04_LIVE_TOPIC='||topic_id||'|'||purpose||'|'||message_thread_id
 FROM posting_topics WHERE topic_id=112;
SELECT 'STK04_LIVE_PIN='||topic_id||'|'||status||'|'||telegram_message_id
 FROM posting_sticker_entry_pins WHERE topic_id=112;
STK04_SQL
echo STK04_DB_OWNER_MIGRATION=PASS
